={{ JSON.stringify({
  model: $env.LLM_MODEL_TAILORING || 'gpt-4o',
  temperature: 0.15,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'You are an ATS Resume Tailoring Agent bound by strict non-fabrication rules. Using ONLY facts, companies, dates, degrees, certifications, skills, and metrics from <source_master_resume>, generate a tailored version aligned with the target job. NEVER fabricate skills, tools, job titles, dates, or numerical metrics. Do NOT add skills from missing_required_skills. Return JSON with keys: tailored_resume (matching the exact schema of source_master_resume), tailoring_summary, clarification_questions_for_user.'
    },
    {
      role: 'user',
      content: `<source_master_resume>${JSON.stringify($json.source_resume)}</source_master_resume>\n<job_match_analysis>${JSON.stringify({
        title: $json.title,
        company: $json.company,
        matching_required_skills: $json.matching_required_skills,
        missing_required_skills_do_not_claim: $json.missing_required_skills
      })}</job_match_analysis>\n<previous_qa_correction_feedback>${$json.qa_error_feedback || 'None'}</previous_qa_correction_feedback>\n<untrusted_job_description>${String($json.job_description).slice(0, 10000)}</untrusted_job_description>`
    }
  ]
}) }}

parameters.jsCode:
const out = [];
const llmItems = $input.all();
const jobItems = $('Postgres: Load Qualifying Jobs Pending Tailoring').all();

for (let i = 0; i < llmItems.length; i++) {
  const raw = llmItems[i].json?.choices?.[0]?.message?.content || '{}';
  const base = jobItems[i]?.json || {};
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsed = { tailored_resume: base.source_resume, tailoring_summary: 'Fallback to source resume' };
  }
  out.push({
    json: {
      ...base,
      tailored_resume: parsed.tailored_resume || base.source_resume,
      tailoring_summary: parsed.tailoring_summary || 'Tailored summary and reordered relevant experience.',
      qa_attempt: (base.qa_attempt || 0) + 1
    }
  });
}
return out;
